final_sql:
SELECT dept, COUNT(course_id) AS number_of_courses
FROM courses
GROUP BY dept;

SELECT dept, COUNT(*) AS enrollments
FROM enrollments JOIN courses ON enrollments.course_id = courses.course_id
GROUP BY dept;

SELECT COUNT(*) 
FROM attendance 
WHERE enrollment_id IN (SELECT enrollment_id FROM enrollments WHERE course_id IN (SELECT course_id FROM courses WHERE dept = 'CSE'));

SELECT admission_year, AVG(cgpa) AS average_cgpa
FROM students
GROUP BY admission_year;
